                              ))
                            ) : (
                              registryAgents.map((agent: RegistryAgent) => {
                                const statusData = socketStatusMap.get(agent.name);
                                return (
                                  <AgentStatusCard
                                    key={agent.name}
                                    agent={agent}
                                    status={statusData?.status || "idle"}
