/**
 * RobotkezV2Agent - Hybrid Browser Automation (Playwright + Browser-Use)
 *
 * Bridge between TypeScript (MCP agent) and Python hybrid engine
 * (myai/agents/robotkez_v2_hybrid.py)
 *
 * Modes:
 * - auto: Complexity analyzer decides (keyword-based)
 * - playwright: Fast, fixed selectors (screenshot, PDF, navigate)
 * - browser-use: AI-powered, flexible (Gemini 2.0 Flash)
 *
 * @author Claude Code + Pohánka Péter
 * @track robotkezv2-hybrid-20260217
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { backgroundTaskManager } from '../utils/backgroundTaskManager.js';
import { persistentBrowser, BrowserCommand } from '../utils/persistentBrowser.js';
import { generateExecutionPlan, ExecutionPlan } from '../utils/llmPlanner.js';

// No longer using execAsync here

export interface RobotkezV2Options {
  mode?: 'auto' | 'playwright' | 'browser-use';
  headless?: boolean;
  screenshot_path?: string;
  pdf_path?: string;
  selector?: string;
  timeout?: number;
  url?: string;
}

export class RobotkezV2Agent extends BaseAgent {
  name = 'RobotkezV2';
  role = 'Magyar Agentic Browser (Comet Stílus)';
  description = 'Folyékonyan kommunikáló, proaktív böngésző ügynök vizuális visszajelzéssel.';
  capabilities = [
    'browser_automation',
    'screenshot',
    'pdf_generation',
    'web_scraping',
    'ai_browsing',
    'multi_step_workflow',
    'magyar_nyelv',
    'agentic_browsing'
  ];

  /**
   * Internal execution logic - implements BaseAgent.executeTask
   */
  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task || '').trim();
    setAgentStatus(this.name, 'working', task.slice(0, 50));

    try {
      // 1. Simple Intent Parsing (Phase 2 compatibility for tests)
      let plan: ExecutionPlan | null = null;
      
      const taskLower = task.toLowerCase();
      if (taskLower.includes('navigálj')) {
        let url = task.match(/https?:\/\/[^\s]+/)?.[0];
        if (!url) {
           const domainMatch = task.match(/([a-z0-9]+\.)+[a-z]{2,}/i);
           if (domainMatch) url = `https://${domainMatch[0]}`;
        }
        
        if (url) {
          plan = {
            plan: [
              { action: 'navigate', url, description: `Navigálás a(z) ${url} weboldalra` }
            ],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        } else {
          // Fallback to search if "navigálj" but no URL
          const query = task.replace(/navigálj/i, '').trim();
          plan = {
            plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(query)}`, description: `Keresés indítása: ${query}` }],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        }
      } else if (taskLower.includes('keress rá')) {
        const query = task.replace(/keress rá a? /i, '').trim();
        plan = {
          plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(query)}`, description: `Google keresés: ${query}` }],
          estimatedDuration: 5000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('kattints')) {
        const selector = task.match(/['"]([^'"]+)['"]/)?.[1] || (taskLower === 'kattints' ? '.primary-button' : null);
        if (selector) {
          plan = {
            plan: [{ action: 'click', selector, description: `Kattintás a(z) '${selector}' elemre` }],
            estimatedDuration: 3000,
            backgroundEligible: false
          };
        }
      } else if (taskLower.includes('írj be') || taskLower.includes('gépelj')) {
        const text = task.match(/['"]([^'"]+)['"]/)?.[1] || 'Hello World';
        const selector = task.match(/a '([^']+)' mezőbe/)?.[1] || 'input';
        plan = {
          plan: [{ action: 'type', selector, text, description: `Szöveg beírása a(z) '${selector}' mezőbe: "${text}"` }],
          estimatedDuration: 4000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('képernyőkép')) {
        plan = {
          plan: [{ action: 'screenshot', description: 'Pillanatkép készítése a jelenlegi oldalról' }],
          estimatedDuration: 3000,
          backgroundEligible: false
        };
      }

      // 2. LLM Plan Generation (if not already parsed or for Phase 3+)
      if (!plan) {
        try {
          // Get current browser state if possible
          let browserState;
          try {
             const stateResponse = await persistentBrowser.sendCommand({ action: 'state' });
             if (stateResponse.status === 'success') {
                browserState = {
                  url: stateResponse.url || '',
                  title: stateResponse.title
                };
             }
          } catch {
             // Ignored
          }

          plan = await generateExecutionPlan(task, {
            history: context.swarm?.history,
            browserState: browserState
          });
        } catch {
          // Final fallback
          plan = {
            plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(task)}`, description: 'Általános keresés indítása' }],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        }
      }

      // 3. Background Delegation (Phase 4.4)
      if (context.backgroundEligible || plan.estimatedDuration > 30000 || plan.backgroundEligible) {
        const taskId = await backgroundTaskManager.startTask(task, plan);
        return {
          success: true,
          message: `Rendben, elindítottam a feladatot a háttérben. A folyamatot a "Background Tasks" panelen követheted nyomon. (Task ID: ${taskId})`,
          data: { taskId, background: true }
        };
      }

      // 4. Sequential Execution via PersistentBrowser
      logInfo(this.name, `Executing plan: ${plan.plan.length} steps`);
      const completedSteps: unknown[] = [];

      for (const step of plan.plan) {
        logInfo(this.name, `Step: ${step.description} (${step.action})`);
        
        try {
          // Strip description and other non-command properties for browser compatibility
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          const { description: _desc, ...command } = step as unknown as Record<string, unknown>;
          // Ensure type safety
          const browserCommand = command as unknown as BrowserCommand;
          const response = await persistentBrowser.sendCommand(browserCommand);
          completedSteps.push({
            ...step,
            status: 'completed',
            result: response
          });
        } catch (stepError: unknown) {
          const msg = stepError instanceof Error ? stepError.message : String(stepError);
          const action = step.action;
          logError(this.name, `Step failed: ${step.description} - ${msg}`);
          completedSteps.push({
            ...step,
            status: 'error',
            error: msg
          });
          
          // Stop on critical error
          if (['navigate', 'click', 'type'].includes(action)) {
             return {
               success: false,
               message: `Sajnos nem sikerült végrehajtani a következő lépést: "${step.description}". Hibaüzenet: ${msg}`
             };
          }
        }
      }

      // 5. Auto-Screenshot (Phase 2 expectation)
      let screenshotResult;
      try {
        screenshotResult = await persistentBrowser.sendCommand({ action: 'screenshot' });
      } catch {
        // Ignored
      }

      const isScreenshotTask = taskLower.includes('képernyőkép');
      const baseMessage = isScreenshotTask
        ? 'Elkészítettem a kért képernyőképet.'
        : `Sikeresen végrehajtottam a feladatot: "${task}".`;

      return {
        success: true,
        message: baseMessage,
        data: {
           completedSteps,
           screenshot: screenshotResult?.screenshot,
           success: true // Legacy support
        }
      };

    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      logError(this.name, `Execution failed: ${msg}`);
      return {
        success: false,
        message: `Hiba történt a végrehajtás során: ${msg}`
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  // Phase 4.4 Background Task Methods
  async executeInBackground(task: string): Promise<{ taskId: string; plan?: ExecutionPlan }> {
    const plan = await generateExecutionPlan(task);
    const taskId = await backgroundTaskManager.startTask(task, plan);
    return { taskId, plan };
  }

  getBackgroundTaskStatus(taskId: string) {
    return backgroundTaskManager.getTaskStatus(taskId);
  }

  cancelBackgroundTask(taskId: string) {
    return backgroundTaskManager.cancelTask(taskId);
  }

  listBackgroundTasks() {
    return backgroundTaskManager.getAllTasks();
  }

  /**
   * Execute with explicit mode (convenience method)
   *
   * @param task - Instruction
   * @param mode - Execution mode
   * @param options - Additional options
   */
  async executeWithMode(
    task: string,
    mode: 'auto' | 'playwright' | 'browser-use',
    options?: Partial<RobotkezV2Options>
  ): Promise<unknown> {
    return this.execute(task, { ...options, mode });
  }

  /**
   * Screenshot convenience method
   *
   * @param url - Target URL
   * @param screenshotPath - Output path (default: screenshot.png)
   */
  async screenshot(url: string, screenshotPath?: string): Promise<unknown> {
    return this.execute(`screenshot ${url}`, {
      mode: 'playwright', // Force Playwright (fast)
      url,
      screenshot_path: screenshotPath || 'screenshot.png'
    });
  }

  /**
   * PDF generation convenience method
   *
   * @param url - Target URL
   * @param pdfPath - Output path (default: page.pdf)
   */
  async generatePdf(url: string, pdfPath?: string): Promise<unknown> {
    return this.execute(`pdf ${url}`, {
      mode: 'playwright', // Force Playwright (fast)
      url,
      pdf_path: pdfPath || 'page.pdf'
    });
  }

  /**
   * AI-powered complex task (force Browser-Use)
   *
   * @param instruction - Natural language instruction
   */
  async aiTask(instruction: string): Promise<unknown> {
    return this.execute(instruction, {
      mode: 'browser-use' // Force AI mode
    });
  }
}

export default RobotkezV2Agent;

/**
 * LLM-based Execution Plan Generator
 *
 * Converts magyar természetes nyelvű utasításokat multi-step execution plan-ekké
 * Ollama/Gemini LLM segítségével
 *
 * @author Claude Code + Pohánka Péter
 * @track robotkezv2-full-comet-20260215
 * @phase Phase 3 - LLM Planning Integration
 */

import { generateRouted } from '../core/llm_client.js';
import { logInfo, logWarn, logError } from './logger.js';

/**
 * Execution Plan Interface
 * LLM generates this structure from user instruction
 */
export interface ExecutionPlan {
    plan: ExecutionStep[];
    estimatedDuration: number;
    requiresUserInput?: string[];
    backgroundEligible: boolean;
    contextNeeded?: string[];
}

/**
 * Execution Step Interface
 * Single atomic browser operation
 */
export interface ExecutionStep {
    action: 'navigate' | 'click' | 'type' | 'scroll' | 'wait' | 'screenshot' | 'extract' | 'press';
    selector?: string;
    url?: string;
    text?: string;
    key?: string; // NEW: for press action
    timeout?: number;
    direction?: 'up' | 'down' | 'left' | 'right';
    amount?: number;
    type?: 'text' | 'attribute' | 'html';
    attribute?: string;
    description: string; // Magyar nyelvű leírás (pl. "Menü megnyitása")
}

/**
 * System Prompt Template
 * Instructs LLM on how to generate execution plans
 */
const SYSTEM_PROMPT = `Te egy intelligens böngésző ügynök vagy, hasonló a Perplexity Comet-hez.
A felhasználó magyar nyelvű utasítást ad, te pedig részletes lépésekre bontod.

ELÉRHETŐ MŰVELETEK:
- navigate(url): Navigálás URL-re
- click(selector): Kattintás CSS selector alapján (pl. ".button", "#submit", "a.link")
- type(selector, text): Szöveg gépelés input mezőbe
- press(key): Billentyű megnyomása (pl. "Enter", "Tab", "Escape")
- scroll(direction, amount): Görgetés (direction: up/down/left/right, amount: pixels)
- wait(selector, timeout): Várakozás elem megjelenésére (timeout ms-ben)
- screenshot(): Képernyőkép készítés
- extract(selector, type): Adat kinyerés (type: text/attribute/html)

SZABÁLYOK:
1. Minden lépésnek legyen magyar description (pl. "Google megnyitása")
2. Használj wait()-et oldal betöltés után (selector: tipikusan első interaktív elem)
3. CSS selectorok legyenek ÁLTALÁNOSAK, NE használj specifikus ID-kat!
   - ✅ JÓ: "input[type='search']", "textarea[name='q']", "button[type='submit']"
   - ❌ ROSSZ: "#gbqfq", "#search-box-id", "#specific-unique-id"
4. Wait timeout legyen HOSSZÚ (min 8000-10000ms), mert oldalak lassan tölthetnek!
5. Estimated duration legyen reális (ms-ben, átlagosan 3-8s/lépés)
6. Ha user input kell (cím, jelszó, stb.), add hozzá a requiresUserInput array-hez
7. backgroundEligible: true ha > 30s várható időtartam
8. Minden navigate után használj wait()-et hogy biztos legyen hogy betöltött az oldal

VÁLASZ FORMÁTUM (CSAK JSON, semmi más):
{
  "plan": [
    { "action": "navigate", "url": "https://example.com", "description": "Példa oldal megnyitása" },
    { "action": "wait", "selector": "input[type='text']", "timeout": 10000, "description": "Input mező betöltésre vár" },
    { "action": "click", "selector": "button[type='submit']", "description": "Submit gomb megnyomása" }
  ],
  "estimatedDuration": 15000,
  "requiresUserInput": [],
  "backgroundEligible": false,
  "contextNeeded": []
}

FONTOS: Csak valid JSON-t adj vissza, semmi más szöveget!

PÉLDA - Google keresés:
Utasítás: "Keress rá az AI hírekre"
Válasz:
{
  "plan": [
    { "action": "navigate", "url": "https://www.google.com", "description": "Google megnyitása" },
    { "action": "wait", "selector": "textarea[name='q']", "timeout": 10000, "description": "Keresőmező betöltése" },
    { "action": "type", "selector": "textarea[name='q']", "text": "AI hírek", "description": "Keresőszó beírása" },
    { "action": "press", "key": "Enter", "description": "Keresés indítása Enterrel" }
  ],
  "estimatedDuration": 20000,
  "requiresUserInput": [],
  "backgroundEligible": false,
  "contextNeeded": []
}`;

/**
 * Generate Execution Plan from magyar instruction
 *
 * @param instruction - Magyar nyelvű utasítás (pl. "Keress rá az AI hírekre")
 * @param options - Contextual options (history, browser state)
 * @returns ExecutionPlan - Multi-step browser automation plan
 * @throws Error if LLM response is invalid or cannot be parsed
 */
export async function generateExecutionPlan(
    instruction: string, 
    options?: { 
        history?: Array<{ role: string, content: string }>,
        browserState?: { url: string, title?: string }
    }
): Promise<ExecutionPlan> {
    logInfo('LLMPlanner', `Generating plan for: "${instruction}"`);

    let contextPrompt = '';
    if (options?.browserState) {
        contextPrompt += `\nJELENLEGI BÖNGÉSZŐ ÁLLAPOT:\n- URL: ${options.browserState.url}\n- Cím: ${options.browserState.title || 'N/A'}\n`;
    }

    if (options?.history && options.history.length > 0) {
        contextPrompt += `\nKORÁBBI BESZÉLGETÉS:\n${options.history.map(h => `${h.role}: ${h.content}`).join('\n')}\n`;
    }

    const userPrompt = `${contextPrompt}\nÚJ UTASÍTÁS: ${instruction}

Készíts részletes execution plan-t a fenti utasítás végrehajtásához, figyelembe véve a kontextust.`;

    try {
        // Call LLM (using Model Router to pick brain model)
        const fullPrompt = `${SYSTEM_PROMPT}\n\n${userPrompt}`;
        const { response } = await generateRouted(fullPrompt, instruction, { category: 'planning' });

        logInfo('LLMPlanner', `Raw LLM response: ${response.slice(0, 200)}...`);

        // Clean up response: extract JSON between first { and last }
        const firstBrace = response.indexOf('{');
        const lastBrace = response.lastIndexOf('}');

        if (firstBrace === -1 || lastBrace === -1 || firstBrace >= lastBrace) {
            throw new Error('No valid JSON object found in LLM response');
        }

        const cleaned = response.slice(firstBrace, lastBrace + 1);

        // Parse JSON
        let plan: ExecutionPlan;
        try {
            plan = JSON.parse(cleaned) as ExecutionPlan;
        } catch (parseError: unknown) {
            const msg = parseError instanceof Error ? parseError.message : String(parseError);
            logError('LLMPlanner', `JSON parse error: ${msg}`);
            logError('LLMPlanner', `Attempted to parse: ${cleaned.slice(0, 500)}`);
            throw new Error(`Invalid JSON from LLM: ${msg}`);
        }

        // Validation
        if (!plan.plan || !Array.isArray(plan.plan)) {
            throw new Error('Invalid plan structure: missing or non-array "plan" field');
        }

        if (plan.plan.length === 0) {
            throw new Error('Invalid plan: empty plan array');
        }

        // Validate each step has required fields
        for (let i = 0; i < plan.plan.length; i++) {
            const step = plan.plan[i];
            if (!step.action) {
                throw new Error(`Invalid step ${i}: missing action`);
            }
            if (!step.description) {
                logWarn('LLMPlanner', `Step ${i} missing description, adding default`);
                step.description = `Lépés ${i + 1}: ${step.action}`;
            }
        }

        // Set defaults
        if (typeof plan.estimatedDuration !== 'number') {
            plan.estimatedDuration = plan.plan.length * 3000; // 3s/step default
            logWarn('LLMPlanner', `Missing estimatedDuration, defaulting to ${plan.estimatedDuration}ms`);
        }

        if (typeof plan.backgroundEligible !== 'boolean') {
            plan.backgroundEligible = plan.estimatedDuration > 30000;
        }

        // POST-PROCESSING: Override short wait timeouts (LLM often generates too short timeouts)
        for (const step of plan.plan) {
            if (step.action === 'wait') {
                if (!step.timeout || step.timeout < 10000) {
                    const oldTimeout = step.timeout || 0;
                    step.timeout = 10000; // Force 10s minimum for wait actions
                    logWarn('LLMPlanner', `⚠️ Overriding wait timeout ${oldTimeout}ms → 10000ms for selector: ${step.selector}`);
                }
            }
        }

        logInfo('LLMPlanner', `✅ Plan generated: ${plan.plan.length} steps, ${plan.estimatedDuration}ms`);

        return plan;

    } catch (error: unknown) {
        const msg = error instanceof Error ? error.message : String(error);
        logError('LLMPlanner', `Failed to generate plan: ${msg}`);
        throw error;
    }
}

/**
 * Validate Execution Plan structure
 * (Additional runtime validation beyond LLM generation)
 *
 * @param plan - ExecutionPlan to validate
 * @returns boolean - true if valid
 * @throws Error with detailed message if invalid
 */
export function validateExecutionPlan(plan: ExecutionPlan): boolean {
    if (!plan.plan || !Array.isArray(plan.plan)) {
        throw new Error('Invalid plan: missing or non-array "plan" field');
    }

    const validActions = ['navigate', 'click', 'type', 'scroll', 'wait', 'screenshot', 'extract'];

    for (let i = 0; i < plan.plan.length; i++) {
        const step = plan.plan[i];

        // Validate action
        if (!validActions.includes(step.action)) {
            throw new Error(`Invalid step ${i}: unknown action "${step.action}"`);
        }

        // Validate required fields per action type
        switch (step.action) {
            case 'navigate':
                if (!step.url) {
                    throw new Error(`Invalid step ${i}: navigate requires "url"`);
                }
                break;
            case 'click':
            case 'wait':
                if (!step.selector) {
                    throw new Error(`Invalid step ${i}: ${step.action} requires "selector"`);
                }
                break;
            case 'type':
                if (!step.selector || step.text === undefined) {
                    throw new Error(`Invalid step ${i}: type requires "selector" and "text"`);
                }
                break;
            case 'extract':
                if (!step.selector) {
                    throw new Error(`Invalid step ${i}: extract requires "selector"`);
                }
                break;
            // scroll and screenshot have no required fields
        }
    }

    return true;
}

import type { ChildProcess } from 'child_process';
import { logInfo, logError } from './logger.js';

export interface BrowserCommand {
    action: 'launch' | 'navigate' | 'click' | 'type' | 'screenshot' | 'content' | 'scroll' | 'wait' | 'extract' | 'close' | 'press' | 'state';
    url?: string;
    selector?: string;
    text?: string;
    key?: string; // NEW: for press action
    headless?: boolean;
    // NEW: scroll parameters
    direction?: 'up' | 'down' | 'left' | 'right';
    amount?: number;
    // NEW: wait parameters
    timeout?: number;
    // NEW: extract parameters
    type?: 'text' | 'attribute' | 'html';
    attribute?: string;
}

export interface BrowserResponse {
    status: 'success' | 'error';
    message?: string;
    url?: string;
    title?: string; // NEW: for state results
    screenshot?: string; // base64
    content?: string;
    data?: unknown; // NEW: for extract results
    count?: number; // NEW: number of extracted elements
}

export class PersistentBrowser {
    private process: ChildProcess | null = null; 
    private lastScreenshot: Uint8Array | null = null;
    private pendingCommands: { resolve: (value: BrowserResponse) => void; reject: (reason?: unknown) => void }[] = [];
    private buffer: string = '';
    private startPromise: Promise<void> | null = null;

    constructor() {}

    private async getPythonPath(): Promise<string> {
        if (typeof process === 'undefined' || !process.versions?.node) return 'python';
        const fs = await import('fs');
        const venvPath = process.platform === 'win32' ? '.venv/Scripts/python.exe' : '.venv/bin/python';
        if (fs.existsSync(venvPath)) {
            return venvPath;
        }
        return 'python';
    }

    private async startProcess() {
        if (this.process) return;
        if (typeof process === 'undefined' || !process.versions?.node) {
             throw new Error("Browser agent only supported in Node.js environment");
        }

        const path = (await import('path')).default;
        const { spawn } = await import('child_process');

        const scriptPath = path.resolve(process.cwd(), 'myai/interactive_browser.py');
        const pythonExec = await this.getPythonPath();

        logInfo('PersistentBrowser', `Starting browser process: ${pythonExec} ${scriptPath}`);

        this.process = spawn(pythonExec, [scriptPath], {
            stdio: ['pipe', 'pipe', 'pipe']
        });

        this.process.stdout?.on('data', (data: Buffer | string) => {
            this.buffer += data.toString();

            const lines = this.buffer.split('\n');
            this.buffer = lines.pop() || ''; // Keep the last partial line

            for (const line of lines) {
                if (!line.trim()) continue;
                try {
                    const response = JSON.parse(line);
                    this.handleResponse(response);
                } catch {
                    logError('PersistentBrowser', `Failed to parse response: ${line}`);
                }
            }
        });

        this.process.stderr?.on('data', (data: Buffer | string) => {
            logError('PersistentBrowser', `Python stderr: ${data.toString()}`);
        });

        this.process.on('close', (code: number | null) => {
            logInfo('PersistentBrowser', `Browser process exited with code ${code}`);
            this.process = null;
            // Reject all pending
            while (this.pendingCommands.length > 0) {
                const { reject } = this.pendingCommands.shift()!;
                reject(new Error('Browser process exited'));
            }
        });
    }

    private handleResponse(response: BrowserResponse) {
        if (this.pendingCommands.length > 0) {
            const { resolve, reject } = this.pendingCommands.shift()!;

            if (response.status === 'success') {
                if (response.screenshot) {
                    try {
                        this.lastScreenshot = Buffer.from(response.screenshot, 'base64');
                        // Remove base64 from object to keep it light
                        delete response.screenshot;
                    } catch {
                        logError('PersistentBrowser', 'Failed to decode screenshot');
                    }
                }
                resolve(response);
            } else {
                reject(new Error(response.message || 'Unknown error'));
            }
        }
    }

    public async sendCommand(command: BrowserCommand): Promise<BrowserResponse> {
        if (!this.process) {
            if (!this.startPromise) {
                this.startPromise = this.startProcess();
            }
            try {
                await this.startPromise;
            } catch (e) {
                this.startPromise = null;
                throw new Error("Failed to start browser process: " + String(e));
            }
        }

        return new Promise((resolve, reject) => {
            this.pendingCommands.push({ resolve, reject });
            const jsonCmd = JSON.stringify(command) + '\n';
            if (this.process && this.process.stdin) {
                this.process.stdin.write(jsonCmd);
            } else {
                reject(new Error("Process failed to start or is not running"));
            }
        });
    }

    public getLastScreenshot(): Uint8Array | null {
        return this.lastScreenshot;
    }

    public async close() {
        if (this.process) {
            await this.sendCommand({ action: 'close' }).catch(() => {}); // Ignore error if already closed
            if (this.process) this.process.kill();
            this.process = null;
            this.lastScreenshot = null;
        }
    }
}

export const persistentBrowser = new PersistentBrowser();

import sys
import json
import asyncio
import base64
import os
from playwright.async_api import async_playwright

# Ensure we use unbuffered stdout for JSON communication
# sys.stdout.reconfigure(encoding='utf-8') # Python 3.7+

async def highlight_element(page, selector):
    """
    Highlights an element with a red outline and background for visual feedback.
    """
    try:
        await page.evaluate("""(selector) => {
            const el = document.querySelector(selector);
            if (el) {
                el.style.outline = '3px solid red';
                el.style.backgroundColor = 'rgba(255, 0, 0, 0.1)';
                el.style.transition = 'all 0.3s ease';
                el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }""", selector)
        # Give a short pause for the scroll/style to render before screenshot
        await asyncio.sleep(0.2)
    except Exception:
        pass # Ignore highlighting errors

async def main():
    async with async_playwright() as p:
        browser = None
        context = None
        page = None

        async def get_page():
            nonlocal browser, context, page
            if not browser:
                # Check ROBOTKEZ_HEADLESS first, fallback to HEADLESS
                # Default: true (headless = no browser window visible)
                # Set ROBOTKEZ_HEADLESS=false in .env to see the browser window!
                robotkez_headless = os.getenv("ROBOTKEZ_HEADLESS", os.getenv("HEADLESS", "true"))
                headless = robotkez_headless.lower() == "true"

                # Get viewport settings from env or use defaults
                viewport_width = int(os.getenv("ROBOTKEZ_VIEWPORT_WIDTH", "1280"))
                viewport_height = int(os.getenv("ROBOTKEZ_VIEWPORT_HEIGHT", "720"))

                print(f"[Robotkéz] Böngésző indítás: headless={headless}, viewport={viewport_width}x{viewport_height}", file=sys.stderr)

                browser = await p.chromium.launch(headless=headless, args=['--no-sandbox', '--disable-setuid-sandbox'])
                context = await browser.new_context(viewport={'width': viewport_width, 'height': viewport_height})
                page = await context.new_page()
            return page

        loop = asyncio.get_running_loop()

        while True:
            try:
                line = await loop.run_in_executor(None, sys.stdin.readline)
                if not line:
                    break

                cmd = json.loads(line)
                action = cmd.get("action")
                result = {"status": "error", "message": "Unknown action"}

                if action == "launch":
                    await get_page() # Initializes browser
                    result = {"status": "success", "message": "Browser launched"}

                elif action == "navigate":
                    pg = await get_page()
                    url = cmd.get("url")
                    if url:
                        await pg.goto(url)
                        result = {"status": "success", "url": pg.url}
                        # Capture screenshot after navigation
                        screenshot_bytes = await pg.screenshot(type='png')
                        result["screenshot"] = base64.b64encode(screenshot_bytes).decode('utf-8')
                    else:
                        result = {"status": "error", "message": "URL missing"}

                elif action == "click":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    if selector:
                        try:
                            # 1. Highlight
                            await highlight_element(pg, selector)
                            # 2. Screenshot (Intent)
                            screenshot_bytes = await pg.screenshot(type='png')
                            screenshot_b64 = base64.b64encode(screenshot_bytes).decode('utf-8')

                            # 3. Action
                            await pg.click(selector, timeout=5000)

                            result = {
                                "status": "success",
                                "message": f"Clicked {selector}",
                                "screenshot": screenshot_b64
                            }
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}
                    else:
                        result = {"status": "error", "message": "Selector missing"}

                elif action == "type":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    text = cmd.get("text")
                    if selector and text is not None:
                        try:
                            # 1. Highlight
                            await highlight_element(pg, selector)
                            # 2. Screenshot (Intent)
                            screenshot_bytes = await pg.screenshot(type='png')
                            screenshot_b64 = base64.b64encode(screenshot_bytes).decode('utf-8')

                            # 3. Action
                            await pg.fill(selector, text, timeout=5000)

                            result = {
                                "status": "success",
                                "message": f"Typed into {selector}",
                                "screenshot": screenshot_b64
                            }
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}
                    else:
                        result = {"status": "error", "message": "Selector or text missing"}

                elif action == "screenshot":
                    pg = await get_page()
                    try:
                        screenshot_bytes = await pg.screenshot(type='png')
                        b64 = base64.b64encode(screenshot_bytes).decode('utf-8')
                        result = {"status": "success", "screenshot": b64}
                    except Exception as e:
                        result = {"status": "error", "message": str(e)}

                elif action == "content":
                    pg = await get_page()
                    content = await pg.content()
                    result = {"status": "success", "content": content}

                # ==================== NEW ACTIONS (RobotkezV2) ====================

                elif action == "scroll":
                    pg = await get_page()
                    direction = cmd.get("direction", "down")
                    amount = cmd.get("amount", 100)

                    try:
                        if direction == "down":
                            await pg.evaluate(f"window.scrollBy(0, {amount})")
                        elif direction == "up":
                            await pg.evaluate(f"window.scrollBy(0, -{amount})")
                        elif direction == "left":
                            await pg.evaluate(f"window.scrollBy(-{amount}, 0)")
                        elif direction == "right":
                            await pg.evaluate(f"window.scrollBy({amount}, 0)")
                        else:
                            result = {"status": "error", "message": f"Invalid direction: {direction}"}
                            print(json.dumps(result), flush=True)
                            continue

                        # Screenshot after scroll
                        screenshot_bytes = await pg.screenshot(type='png')
                        screenshot_b64 = base64.b64encode(screenshot_bytes).decode('utf-8')

                        result = {
                            "status": "success",
                            "message": f"Scrolled {direction} by {amount}px",
                            "screenshot": screenshot_b64
                        }
                    except Exception as e:
                        result = {"status": "error", "message": str(e)}

                elif action == "wait":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    timeout = cmd.get("timeout", 5000)

                    if selector:
                        try:
                            await pg.wait_for_selector(selector, timeout=timeout)
                            result = {"status": "success", "message": f"Element {selector} is visible"}
                        except Exception as e:
                            result = {"status": "error", "message": f"Timeout waiting for {selector}: {str(e)}"}
                    else:
                        result = {"status": "error", "message": "Selector missing"}

                elif action == "extract":
                    pg = await get_page()
                    selector = cmd.get("selector")
                    extract_type = cmd.get("type", "text")
                    attribute = cmd.get("attribute")

                    if not selector:
                        result = {"status": "error", "message": "Selector missing"}
                    else:
                        try:
                            elements = await pg.query_selector_all(selector)

                            if extract_type == "text":
                                data = []
                                for el in elements:
                                    text = await el.inner_text()
                                    data.append(text)

                            elif extract_type == "attribute":
                                if not attribute:
                                    result = {"status": "error", "message": "Attribute name missing"}
                                    print(json.dumps(result), flush=True)
                                    continue
                                data = []
                                for el in elements:
                                    attr_value = await el.get_attribute(attribute)
                                    data.append(attr_value)

                            elif extract_type == "html":
                                data = []
                                for el in elements:
                                    html = await el.inner_html()
                                    data.append(html)

                            else:
                                result = {"status": "error", "message": f"Invalid extract type: {extract_type}"}
                                print(json.dumps(result), flush=True)
                                continue

                            result = {"status": "success", "data": data, "count": len(data)}
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}

                elif action == "press":
                    pg = await get_page()
                    key = cmd.get("key")
                    if key:
                        try:
                            await pg.keyboard.press(key)
                            # Screenshot after press
                            screenshot_bytes = await pg.screenshot(type='png')
                            screenshot_b64 = base64.b64encode(screenshot_bytes).decode('utf-8')
                            result = {
                                "status": "success",
                                "message": f"Pressed {key}",
                                "screenshot": screenshot_b64
                            }
                        except Exception as e:
                            result = {"status": "error", "message": str(e)}
                    else:
                        result = {"status": "error", "message": "Key missing"}

                elif action == "state" or action == "status":
                    pg = await get_page()
                    try:
                        url = pg.url
                        title = await pg.title()
                        result = {"status": "success", "url": url, "title": title}
                    except Exception as e:
                        result = {"status": "error", "message": str(e)}

                # ==================== END NEW ACTIONS ====================

                elif action == "close":
                    if browser:
                        await browser.close()
                        browser = None
                        page = None
                        context = None
                    result = {"status": "success", "message": "Browser closed"}

                print(json.dumps(result), flush=True)

            except json.JSONDecodeError:
                print(json.dumps({"status": "error", "message": "Invalid JSON"}), flush=True)
            except Exception as e:
                print(json.dumps({"status": "error", "message": str(e)}), flush=True)

if __name__ == "__main__":
    # Windows fix: Use ProactorEventLoop (default in Python 3.8+)
    # Playwright requires ProactorEventLoop on Windows
    if sys.platform == 'win32':
        # For Python 3.8+, ProactorEventLoop is default - no need to set
        # WindowsSelectorEventLoopPolicy causes issues with Playwright subprocess
        pass

    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass

