import { generateExecutionPlan } from '../src/utils/llmPlanner.js';
import { logInfo } from '../src/utils/logger.js';
import dotenv from 'dotenv';

dotenv.config();

async function debugPlan() {
    const task = "Hozz létre egy új szolgáltatásfiókot a Google Cloud-ban 'brunella-worker' néven, és adj neki 'Storage Admin' jogosultságot.";
    console.log(`\n🎯 TESZT UTASÍTÁS: "${task}"\n`);
    console.log("--- Tervezés folyamatban... ---\n");

    try {
        const plan = await generateExecutionPlan(task);
        console.log("✅ GENERÁLT COMET-STÍLUSÚ TERV:");
        console.log(JSON.stringify(plan, null, 2));

        console.log("\n--- Elemzés ---");
        console.log(`Lépések száma: ${plan.plan.length}`);
        console.log(`Becsült idő: ${plan.estimatedDuration / 1000} másodperc`);
        if (plan.requiresUserInput?.length) {
            console.log(`Szükséges adatok tőled: ${plan.requiresUserInput.join(', ')}`);
        }
    } catch (error) {
        console.error("❌ Hiba a tervezés során:", error.message);
    }
}

debugPlan();

