                }

                // Display unstaged files
                if (status.unstaged.length > 0) {
                    console.log(`\n${chalk.bold('📝 Unstaged changes:')}`);
                    for (const file of status.unstaged) {
                        console.log(`  ${chalk.yellow(`M ${file.path}`)} (${file.status})`);
