                return;
            }

            res.json({ task });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            logError('DeveloperRoute', `Queue get failed: ${msg}`);
            res.status(500).json({ error: msg });
        }
