                        const lineRef = f.line ? chalk.dim(`:${f.line}`) : '';
                        const rule = f.rule ? chalk.dim(` [${f.rule}]`) : '';
                        console.log(`  ${icon} ${f.message}${lineRef}${rule}`);
                        if (f.suggestion) {
                            console.log(`    ${chalk.dim('→')} ${chalk.cyan(f.suggestion)}`);
